package com.example.eac_backend_project.files;
import org.springframework.stereotype.Component;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.server.ResponseStatusException;import static org.springframework.http.HttpStatus.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import javax.crypto.Cipher;import javax.crypto.spec.*;
/** Authenticated encryption bound to the document id; the stable master key stays outside the database. */
@Component public class OfficePasswordCipher {
 private final String configured;private final SecureRandom random=new SecureRandom();
 public OfficePasswordCipher(@Value("${app.files.password-key:}")String configured){this.configured=configured;}
 private SecretKeySpec key()throws GeneralSecurityException{if(configured==null||configured.startsWith("replace-")||configured.equals("change-me")||configured.getBytes(StandardCharsets.UTF_8).length<32)throw new ResponseStatusException(SERVICE_UNAVAILABLE,"Configure a stable APP_FILES_PASSWORD_KEY of at least 32 characters before remembering document passwords");return new SecretKeySpec(MessageDigest.getInstance("SHA-256").digest(("eac-office-password-v1:"+configured).getBytes(StandardCharsets.UTF_8)),"AES");}
 private byte[] aad(Long file){return ("eac-office-opening-password:v1:"+file).getBytes(StandardCharsets.UTF_8);}
 public String seal(Long file,char[] password){byte[] plain=new String(password).getBytes(StandardCharsets.UTF_8);try{byte[] nonce=new byte[12];random.nextBytes(nonce);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key(),new GCMParameterSpec(128,nonce));c.updateAAD(aad(file));byte[] encrypted=c.doFinal(plain);byte[] box=new byte[nonce.length+encrypted.length];System.arraycopy(nonce,0,box,0,nonce.length);System.arraycopy(encrypted,0,box,nonce.length,encrypted.length);return "v1."+Base64.getEncoder().encodeToString(box);}catch(GeneralSecurityException e){throw new ResponseStatusException(SERVICE_UNAVAILABLE,"Could not encrypt the document password; nothing was stored");}finally{Arrays.fill(plain,(byte)0);}}
 public char[] open(Long file,String box){try{if(box==null||!box.startsWith("v1."))throw new GeneralSecurityException();byte[] data=Base64.getDecoder().decode(box.substring(3));if(data.length<28||data.length>4096)throw new GeneralSecurityException();Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Arrays.copyOf(data,12)));c.updateAAD(aad(file));byte[] plain=c.doFinal(data,12,data.length-12);try{return new String(plain,StandardCharsets.UTF_8).toCharArray();}finally{Arrays.fill(plain,(byte)0);}}catch(GeneralSecurityException|IllegalArgumentException e){throw new ResponseStatusException(SERVICE_UNAVAILABLE,"The remembered document password cannot be unlocked with this server key. Restore APP_FILES_PASSWORD_KEY or verify the document password again.");}}
}
